<?php require_once __DIR__.'/includes/auth.php';$page_title='Users';if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$id=(int)$_POST['id'];$status=$_POST['status']==='DISABLED'?'DISABLED':'ACTIVE';db()->prepare('UPDATE users SET status=? WHERE id=? AND is_admin=0')->execute([$status,$id]);log_activity('User status changed',(int)$admin['id'],['user_id'=>$id,'status'=>$status]);flash('success','User status updated.');go('users.php');}$rows=db()->query('SELECT * FROM users WHERE is_admin=0 ORDER BY created_at DESC')->fetchAll();include __DIR__.'/includes/header.php';?><div class="page-title"><div><h1>Users</h1><p>Manage public account access.</p></div></div><section class="panel"><div class="table-wrap"><table class="table"><thead><tr><th>NAME</th><th>USERNAME</th><th>CONTACT</th><th>JOINED</th><th>STATUS</th><th>ACTION</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['name'])?></strong></td><td><?=e($r['username'])?></td><td><?=e($r['email']?:$r['phone'])?></td><td><?=e(date('d M Y',strtotime($r['created_at'])))?></td><td><span class="status <?=strtolower(e($r['status']))?>"><?=e($r['status'])?></span></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$r['id']?>"><input type="hidden" name="status" value="<?=$r['status']==='ACTIVE'?'DISABLED':'ACTIVE'?>"><button class="button <?= $r['status']==='ACTIVE'?'button-danger':'button-green' ?>" data-confirm="Change user status?"><?=$r['status']==='ACTIVE'?'DISABLE':'ENABLE'?></button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php include __DIR__.'/includes/footer.php';?>
